<script lang="ts">
 import {onMount} from 'svelte';
 import type {IncomingView} from '@ash/shared';
 let {api,onInspect,onThread,onClose}:{api:<T>(path:string,body?:object)=>Promise<T>;onInspect:(id:string)=>void;onThread:(id:string)=>void;onClose:()=>void}=$props();
 let dialog:HTMLDialogElement;
 let items=$state<IncomingView[]>([]),error=$state(''),text=$state(''),busy=$state(false),next=$state<string|null>(null),creating=$state(false);
 let polling=false;
 async function refreshActive(){if(polling)return;polling=true;try{const active=items.filter(i=>['queued','processing','waiting_capacity'].includes(i.status)||['queued','running'].includes(i.runStatus??'')).slice(0,20);const updates=new Map((await Promise.all(active.map(i=>api<IncomingView>('incoming/'+i.id)))).map(i=>[i.id,i]));items=items.map(i=>updates.get(i.id)??i);}catch(e){error=(e as Error).message;}finally{polling=false;}}
 let command=$state<{id:string;source:{name:string;eventId:string;label:string};text:string}|null>(null);
 async function load(more=false){try{const page=await api<{items:IncomingView[];next:string|null}>('incoming'+(more&&next?'?before='+next:''));items=more?[...items,...page.items]:page.items;next=page.next;}catch(e){error=(e as Error).message;}}
 async function receive(){busy=true;error='';command??={id:crypto.randomUUID(),source:{name:'synthetic',eventId:crypto.randomUUID(),label:'Synthetic inbox'},text:text.trim()};try{await api('incoming',command);text='';command=null;creating=false;await load();}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function retry(id:string){busy=true;error='';try{await api('incoming/'+id+'/retry',{});await load();}catch(e){error=(e as Error).message;}finally{busy=false;}}
 const labels:Record<string,string>={queued:'Queued',processing:'Processing',waiting_capacity:'Waiting for Thread',completed:'Processed',dropped:'Filtered out',failed:'Failed',interrupted:'Interrupted'};
 onMount(()=>{const previous=document.activeElement as HTMLElement;dialog.showModal();void load();const timer=setInterval(()=>{void refreshActive();},1000);return()=>{clearInterval(timer);previous?.focus({preventScroll:true});};});
</script>
<dialog bind:this={dialog} aria-label="Incoming processing" oncancel={event=>{event.preventDefault();onClose();}}>
 <header><div><span>ARTIFACTS</span><h2>Processing</h2></div><button aria-label="Close processing" onclick={onClose}>×</button></header>
 <div class="toolbar"><p>Incoming sources and their recorded outcomes.</p><button onclick={()=>void load()}>Refresh</button><button onclick={()=>creating=!creating}>Add synthetic item</button></div>
 {#if error}<p class="error" role="alert">{error}</p>{/if}
 {#if creating}<form onsubmit={event=>{event.preventDefault();void receive();}}><label for="incoming-text">Synthetic source text</label><textarea id="incoming-text" bind:value={text} maxlength={8000} disabled={busy||!!command} placeholder="October rent receipt — paid in full."></textarea><div><button disabled={busy||!text.trim()}>{busy?'Saving…':'Process item'}</button>{#if command}<button type="button" onclick={()=>{command=null;error='';}}>Edit as new item</button>{/if}</div></form>{/if}
 <div class="items">{#each items as item(item.id)}<article><div class="item-heading"><strong>{item.input.source.label}</strong><span>{labels[item.status]+(item.runStatus?' · Work '+item.runStatus:'')}</span></div><p>{item.input.text.length>220?item.input.text.slice(0,220)+'…':item.input.text}</p>{#if item.error}<p class="error">{item.error}</p>{/if}<div class="actions"><time>{new Date(item.createdAt).toLocaleString()}</time><button onclick={()=>{onClose();onInspect(item.id);}}>Inspect item</button>{#if item.state.threadId&&item.status!=='dropped'}<button onclick={()=>{onClose();onThread(item.state.threadId!);}}>Open Thread</button>{/if}{#if ['failed','interrupted'].includes(item.status)}<button disabled={busy} onclick={()=>void retry(item.id)}>Retry processing</button>{/if}</div></article>{:else}<p class="empty">No incoming items yet.</p>{/each}{#if next}<button onclick={()=>void load(true)}>Load older items</button>{/if}</div>
</dialog>
<style>
 dialog{width:min(720px,calc(100vw - 48px));max-height:calc(100vh - 80px);padding:0;border:1px solid #d7dfce;border-radius:12px;background:#f7f8f2;color:#3f5134;box-shadow:0 24px 80px #24371a20}dialog::backdrop{background:#283b2528}header{display:flex;justify-content:space-between;align-items:center;padding:24px 28px 12px}header span{font-size:10px;letter-spacing:.12em;color:#7d8c71}h2{font-size:22px;font-weight:500;margin:5px 0}button{border:0;border-radius:4px;background:transparent;color:var(--accent,#506c3c);padding:6px 8px;font:inherit;font-size:12px;cursor:pointer}button:hover{background:#e6ebdf}button:disabled{opacity:.5}header button{font-size:24px}.toolbar{display:flex;align-items:center;gap:8px;padding:0 20px 15px 28px;border-bottom:1px solid #dce2d3}.toolbar p{flex:1;font-size:12px;color:#77836f}.items{padding:0 28px 20px;max-height:55vh;overflow:auto}article{padding:20px 0;border-bottom:1px solid #dce2d3}.item-heading{display:flex;justify-content:space-between;gap:16px;font-size:12px}.item-heading span{color:#77836f}article p{font-size:13px;line-height:1.6;white-space:pre-wrap;overflow-wrap:anywhere}.actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}time{font-size:10px;color:#84907b;margin-right:auto}.empty{padding:35px 0;color:#7d8c71;font-size:13px}.error{color:#986d4c;padding:0 28px;font-size:12px}article .error{padding:0}form{padding:20px 28px;border-bottom:1px solid #dce2d3}label{display:block;font-size:12px;margin-bottom:8px}textarea{box-sizing:border-box;width:100%;min-height:100px;padding:10px;background:#fffefa;border:1px solid #d7dfce;border-radius:6px;color:inherit;font:inherit;font-size:13px;resize:vertical}
</style>
